export const GET_SAVED_CART_ENDPOINT_ALIAS = 'getSavedCart';
export const CLONE_SAVED_CART_ENDPOINT_ALIAS = 'cloneSavedCart';
export const DELETE_CART_ENDPOINT_ALIAS = 'deleteCart';
