  isAccount: boolean,
  orderType: string,
  conf: TabbingOrderConfig = config
) {
  verifyReviewOrderPage();

  if (isAccount) {
    cy.get('.cx-review-summary-card')
      .contains('cx-card', 'Purchase Order Number')
      .find('.cx-card-container')
      .within(() => {
        cy.findByText(poNumber);
      });

    cy.get('.cx-review-summary-card')
